import { type MigrateDownArgs, type MigrateUpArgs, sql } from '@payloadcms/db-postgres'

/**
 * QA report 2026-10-08 — keuangan (QA-04, QA-06, QA-17; ADR 0019). Schema part as generated by
 * `payload migrate:create qa_finance_integrity` (snapshot in the .json), written re-runnable (IF NOT EXISTS /
 * guarded DO blocks), run as <prefix>_owner, plus hand-written guards. ADDITIVE for the previous web image and
 * every released APK (new nullable columns, new enum values, new triggers that only act on new writes):
 *
 * 1. `audit_logs.action` += 'overdraft_confirmed' (QA-04), 'bank_unverified_confirmed' (QA-17).
 * 2. `companies.shortfall_tolerance_pct` numeric DEFAULT 10 NOT NULL, CHECK 0–100 (QA-06, owner decision).
 * 3. Shortfall re-approval (ADR 0019):
 *    - `settlements.shortfall_approval_*` (status enum, cycle, level, amount, snapshot, note, reject reason);
 *      `pk_settlements_guard` (CREATE OR REPLACE, E9 body + this block): the columns change only while the LPJ
 *      stays verified, following none|rejected → pending_* (new cycle) → … → approved|rejected; amount/rule/note
 *      fixed per cycle; a rejection needs a reason; new LPJ rows carry none of it;
 *    - `approvals.doc_type` += 'expense_shortfall' and `approvals.settlement_id` (FK, index): CHECK
 *      `approvals_owner_doc` gets the third owner kind; G1 trigger `pk_approvals_before_insert` refuses the
 *      requester/creator of the settlement's request; one decision per (settlement, cycle, position, level) and
 *      one position per person per cycle (unique indexes, like requests/addenda); `approvals_company_refs`
 *      also checks `settlement_id` (same PT);
 *    - trigger `transfers_shortfall_tolerance` (BEFORE INSERT, kind lpj_shortfall): transferred total after the
 *      shortfall ≤ approved + ⌊approved × tolerance / 100⌋ unless the LPJ's shortfall approval is `approved`
 *      for at least that total — the service answers 409 SHORTFALL_REAPPROVAL_REQUIRED first.
 * Comparisons with the NEW enum values use `::text` (a value added by ALTER TYPE … ADD VALUE cannot be used as an
 * enum literal in the same transaction).
 */
export async function up({ db }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
    DO $pk$
    BEGIN
      IF current_user !~ '_owner$' THEN
        RAISE EXCEPTION 'migrations must run as the <prefix>_owner role (current_user=%)', current_user;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'enum_settlements_shortfall_approval_status') THEN
        CREATE TYPE "public"."enum_settlements_shortfall_approval_status" AS ENUM('pending_ack', 'pending_approval', 'approved', 'rejected');
      END IF;
    END
    $pk$;
  ALTER TYPE "public"."enum_approvals_doc_type" ADD VALUE IF NOT EXISTS 'expense_shortfall';
  ALTER TYPE "public"."enum_audit_logs_action" ADD VALUE IF NOT EXISTS 'overdraft_confirmed';
  ALTER TYPE "public"."enum_audit_logs_action" ADD VALUE IF NOT EXISTS 'bank_unverified_confirmed';
  ALTER TABLE "companies" ADD COLUMN IF NOT EXISTS "shortfall_tolerance_pct" numeric DEFAULT 10 NOT NULL;
  ALTER TABLE "approvals" ADD COLUMN IF NOT EXISTS "settlement_id" integer;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_status" "enum_settlements_shortfall_approval_status";
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_cycle" numeric DEFAULT 0;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_level" numeric;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_amount" numeric;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_snapshot" jsonb;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_approval_note" varchar;
  ALTER TABLE "settlements" ADD COLUMN IF NOT EXISTS "shortfall_reject_reason" varchar;
  CREATE INDEX IF NOT EXISTS "approvals_settlement_idx" ON "approvals" USING btree ("settlement_id");`)

  await db.execute(sql`
    DO $pk$
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'approvals_settlement_id_settlements_id_fk') THEN
        ALTER TABLE "approvals" ADD CONSTRAINT "approvals_settlement_id_settlements_id_fk" FOREIGN KEY ("settlement_id") REFERENCES "public"."settlements"("id") ON DELETE set null ON UPDATE no action;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'companies_shortfall_tolerance_pct') THEN
        ALTER TABLE companies ADD CONSTRAINT companies_shortfall_tolerance_pct CHECK (shortfall_tolerance_pct >= 0 AND shortfall_tolerance_pct <= 100);
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'settlements_shortfall_approval') THEN
        ALTER TABLE settlements ADD CONSTRAINT settlements_shortfall_approval CHECK (
          coalesce(shortfall_approval_cycle, 0) >= 0
          AND (shortfall_approval_status IS NULL OR (
            shortfall_approval_cycle >= 1 AND shortfall_approval_snapshot IS NOT NULL
            AND shortfall_approval_amount > 0 AND shortfall_approval_amount = trunc(shortfall_approval_amount))));
      END IF;
    END
    $pk$;

    -- approvals: third owner kind (doc_type compared as text: the enum value is new in this transaction)
    ALTER TABLE approvals DROP CONSTRAINT IF EXISTS approvals_owner_doc;
    ALTER TABLE approvals ADD CONSTRAINT approvals_owner_doc CHECK (
      (doc_type::text = 'expense_request' AND request_id IS NOT NULL AND addendum_id IS NULL AND settlement_id IS NULL)
      OR (doc_type::text = 'budget_addendum' AND addendum_id IS NOT NULL AND request_id IS NULL AND settlement_id IS NULL)
      OR (doc_type::text = 'expense_shortfall' AND settlement_id IS NOT NULL AND request_id IS NULL AND addendum_id IS NULL));

    CREATE OR REPLACE FUNCTION pk_approvals_before_insert() RETURNS trigger LANGUAGE plpgsql AS $fn$
    DECLARE
      creator integer;
      rid integer;
    BEGIN
      NEW.decided_at := clock_timestamp();
      IF NEW.position IN ('diketahui', 'approval') THEN
        IF NEW.doc_type::text = 'budget_addendum' THEN
          SELECT created_by_id INTO creator FROM budget_addenda WHERE id = NEW.addendum_id;
          IF NEW.actor_id IS NULL OR creator IS NULL OR NEW.actor_id = creator THEN
            RAISE EXCEPTION 'approvals: the addendum creator cannot hold a decision position (G1)' USING ERRCODE = '42501';
          END IF;
          RETURN NEW;
        END IF;
        -- QA-06 / ADR 0019: a shortfall decision is about the settlement's request (same G1 rule)
        rid := NEW.request_id;
        IF NEW.doc_type::text = 'expense_shortfall' THEN
          SELECT request_id INTO rid FROM settlements WHERE id = NEW.settlement_id;
        END IF;
        SELECT created_by_id INTO creator FROM expense_requests WHERE id = rid;
        IF NEW.actor_id IS NULL OR NEW.actor_id = creator OR EXISTS (
             SELECT 1 FROM expense_requests_rels r JOIN company_memberships m ON m.employee_id = r.employees_id
             WHERE r.parent_id = rid AND r.path = 'requesters' AND m.user_id = NEW.actor_id) THEN
          RAISE EXCEPTION 'approvals: requester/creator cannot hold a decision position (G1)' USING ERRCODE = '42501';
        END IF;
      END IF;
      RETURN NEW;
    END
    $fn$;

    CREATE UNIQUE INDEX IF NOT EXISTS approvals_settlement_one_decision_per_level ON approvals (settlement_id, cycle, position, level)
      WHERE settlement_id IS NOT NULL AND decision IN ('acknowledged', 'approved', 'rejected');
    CREATE UNIQUE INDEX IF NOT EXISTS approvals_settlement_one_position_per_person ON approvals (settlement_id, cycle, actor_id)
      WHERE settlement_id IS NOT NULL AND position IN ('diketahui', 'approval');

    DROP TRIGGER IF EXISTS approvals_company_refs ON approvals;
    CREATE TRIGGER approvals_company_refs BEFORE INSERT OR UPDATE ON approvals FOR EACH ROW
      EXECUTE FUNCTION pk_same_company('request_id', 'expense_requests', 'addendum_id', 'budget_addenda', 'employee_id', 'employees', 'settlement_id', 'settlements');

    CREATE OR REPLACE FUNCTION pk_transfers_shortfall_tolerance() RETURNS trigger LANGUAGE plpgsql AS $fn$
    DECLARE
      r record;
      s record;
      tol numeric;
      approved numeric;
      total numeric;
    BEGIN
      SELECT approved_amount, transferred_total, company_id INTO r FROM expense_requests WHERE id = NEW.request_id;
      SELECT shortfall_approval_status::text AS st, shortfall_approval_amount AS amt INTO s FROM settlements WHERE request_id = NEW.request_id;
      SELECT least(100, greatest(0, coalesce(shortfall_tolerance_pct, 10))) INTO tol FROM companies WHERE id = r.company_id;
      approved := coalesce(r.approved_amount, 0);
      total := coalesce(r.transferred_total, 0) + NEW.amount;
      IF total > approved + floor(approved * coalesce(tol, 10) / 100) AND NOT coalesce(s.st = 'approved' AND s.amt >= total, false) THEN
        RAISE EXCEPTION 'transfers: LPJ shortfall makes the transferred total % exceed approved % + tolerance % percent without re-approval (ADR 0019)', total, approved, tol
          USING ERRCODE = '42501';
      END IF;
      RETURN NEW;
    END
    $fn$;
    DROP TRIGGER IF EXISTS transfers_shortfall_tolerance ON transfers;
    CREATE TRIGGER transfers_shortfall_tolerance BEFORE INSERT ON transfers FOR EACH ROW
      WHEN (NEW.kind = 'lpj_shortfall') EXECUTE FUNCTION pk_transfers_shortfall_tolerance();
`)

  // pk_settlements_guard: E9 body (20260926_131136_s3a_e9_hardening) + the shortfall approval block
  await db.execute(sql`
    CREATE OR REPLACE FUNCTION pk_settlements_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
    DECLARE
      r record;
      o jsonb;
      n jsonb;
      submit_cols text[] := ARRAY['usage_notes', 'transferred_total', 'receipts_total', 'difference', 'submit_count',
                                  'submitted_at', 'submitted_by_id', 'doc_no'];
      verify_cols text[] := ARRAY['transferred_total', 'verified_receipts_total', 'difference', 'settlement_type',
                                  'verified_at', 'verified_by_id'];
      settle_cols text[] := ARRAY['settled_at', 'settled_by_id', 'refund_cash_entry_id', 'shortfall_transfer_id'];
      reverse_cols text[] := ARRAY['reversal_count', 'last_reversed_at', 'last_reversed_by_id', 'last_reversal_reason'];
      approval_cols text[] := ARRAY['shortfall_approval_status', 'shortfall_approval_cycle', 'shortfall_approval_level', 'shortfall_approval_amount',
                                    'shortfall_approval_snapshot', 'shortfall_approval_note', 'shortfall_reject_reason'];
      os text;
      ns text;
      entering boolean;
      always text[] := ARRAY['status', 'updated_at'];
      allowed text[];
      reversing boolean;
      ce record;
      tr record;
    BEGIN
      SELECT type::text AS type, status::text AS status INTO r FROM expense_requests WHERE id = NEW.request_id;
      IF TG_OP = 'INSERT' THEN
        IF r.type IS DISTINCT FROM 'advance' THEN
          RAISE EXCEPTION 'settlements: LPJ exists only for Uang Muka (request %)', NEW.request_id USING ERRCODE = '42501';
        END IF;
        IF NEW.status <> 'draft' OR NEW.doc_no IS NOT NULL OR NEW.settled_at IS NOT NULL OR NEW.verified_at IS NOT NULL
           OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL
           OR coalesce(NEW.reversal_count, 0) <> 0 OR NEW.last_reversed_at IS NOT NULL OR NEW.last_reversed_by_id IS NOT NULL
           OR NEW.last_reversal_reason IS NOT NULL
           OR NEW.shortfall_approval_status IS NOT NULL OR coalesce(NEW.shortfall_approval_cycle, 0) <> 0 OR NEW.shortfall_approval_amount IS NOT NULL THEN
          RAISE EXCEPTION 'settlements: new LPJ rows are drafts' USING ERRCODE = '42501';
        END IF;
        RETURN NEW;
      END IF;

      o := to_jsonb(OLD);
      n := to_jsonb(NEW);
      -- E9: the ONLY change of a settled row is the reversal settled → verified (Finance, reason).
      reversing := OLD.status = 'settled' AND NEW.status = 'verified';
      IF OLD.status = 'settled' AND NOT reversing AND (o - 'updated_at') IS DISTINCT FROM (n - 'updated_at') THEN
        RAISE EXCEPTION 'settlements %: settled LPJ is immutable', OLD.id USING ERRCODE = '42501';
      END IF;
      IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
           (OLD.status = 'draft' AND NEW.status = 'submitted') OR (OLD.status = 'submitted' AND NEW.status IN ('revision', 'verified'))
           OR (OLD.status = 'revision' AND NEW.status = 'submitted') OR (OLD.status = 'verified' AND NEW.status = 'settled')
           OR reversing) THEN
        RAISE EXCEPTION 'settlements %: status % → % not allowed', OLD.id, OLD.status, NEW.status USING ERRCODE = '42501';
      END IF;
      allowed := always;
      IF NEW.status = 'submitted' AND OLD.status IN ('draft', 'revision') THEN allowed := allowed || submit_cols; END IF;
      IF NEW.status = 'revision' AND OLD.status = 'submitted' THEN allowed := allowed || ARRAY['finance_notes']; END IF;
      IF NEW.status = 'verified' AND OLD.status = 'submitted' THEN allowed := allowed || verify_cols; END IF;
      IF NEW.status = 'settled' AND OLD.status = 'verified' THEN allowed := allowed || settle_cols; END IF;
      IF reversing THEN allowed := allowed || settle_cols || reverse_cols; END IF;
      -- QA-06 / ADR 0019: the shortfall re-approval runs while the LPJ stays verified
      IF OLD.status = 'verified' AND NEW.status = 'verified' THEN allowed := allowed || approval_cols; END IF;
      IF (o - allowed) IS DISTINCT FROM (n - allowed) THEN
        RAISE EXCEPTION 'settlements %: columns outside the % transition cannot change', OLD.id, NEW.status USING ERRCODE = '42501';
      END IF;

      IF (o -> 'shortfall_approval_status', o -> 'shortfall_approval_cycle', o -> 'shortfall_approval_level', o -> 'shortfall_approval_amount',
          o -> 'shortfall_approval_snapshot', o -> 'shortfall_approval_note', o -> 'shortfall_reject_reason')
         IS DISTINCT FROM
         (n -> 'shortfall_approval_status', n -> 'shortfall_approval_cycle', n -> 'shortfall_approval_level', n -> 'shortfall_approval_amount',
          n -> 'shortfall_approval_snapshot', n -> 'shortfall_approval_note', n -> 'shortfall_reject_reason') THEN
        -- QA-06 / ADR 0019 status graph: (none | rejected) → pending_* (new cycle, amount/snapshot/note set once per
        -- cycle); pending_ack → pending_approval | approved | rejected; pending_approval → (next level) | approved | rejected.
        os := OLD.shortfall_approval_status::text;
        ns := NEW.shortfall_approval_status::text;
        entering := coalesce(coalesce(os, 'rejected') = 'rejected' AND ns IN ('pending_ack', 'pending_approval'), false);
        IF NEW.settlement_type IS DISTINCT FROM 'shortfall' THEN
          RAISE EXCEPTION 'settlements %: shortfall approval only for a shortfall LPJ', OLD.id USING ERRCODE = '42501';
        END IF;
        IF NOT coalesce(
             (entering AND NEW.shortfall_approval_cycle = coalesce(OLD.shortfall_approval_cycle, 0) + 1)
          OR (os = 'pending_ack' AND ns IN ('pending_approval', 'approved', 'rejected') AND NEW.shortfall_approval_cycle = OLD.shortfall_approval_cycle)
          OR (os = 'pending_approval' AND ns IN ('pending_approval', 'approved', 'rejected') AND NEW.shortfall_approval_cycle = OLD.shortfall_approval_cycle), false) THEN
          RAISE EXCEPTION 'settlements %: shortfall approval % → % not allowed', OLD.id, coalesce(os, 'none'), coalesce(ns, 'none') USING ERRCODE = '42501';
        END IF;
        IF NOT entering AND ((o -> 'shortfall_approval_amount', o -> 'shortfall_approval_snapshot', o -> 'shortfall_approval_note')
                             IS DISTINCT FROM (n -> 'shortfall_approval_amount', n -> 'shortfall_approval_snapshot', n -> 'shortfall_approval_note')) THEN
          RAISE EXCEPTION 'settlements %: shortfall approval amount/rule/note are fixed per cycle', OLD.id USING ERRCODE = '42501';
        END IF;
        IF ns = 'rejected' AND length(coalesce(NEW.shortfall_reject_reason, '')) < 3 THEN
          RAISE EXCEPTION 'settlements %: shortfall rejection needs a reason', OLD.id USING ERRCODE = '23514';
        END IF;
      END IF;

      IF NEW.status = 'verified' AND OLD.status = 'submitted' THEN
        IF NEW.verified_receipts_total IS NULL OR NEW.transferred_total IS NULL
           OR NEW.difference IS DISTINCT FROM NEW.transferred_total - NEW.verified_receipts_total
           OR NEW.settlement_type IS DISTINCT FROM (CASE WHEN NEW.difference > 0 THEN 'refund' WHEN NEW.difference < 0 THEN 'shortfall' ELSE 'none' END)::enum_settlements_settlement_type THEN
          RAISE EXCEPTION 'settlements %: verified totals are inconsistent', OLD.id USING ERRCODE = '23514';
        END IF;
      END IF;

      IF NEW.status = 'settled' AND OLD.status = 'verified' THEN
        -- links are set once per settlement cycle (a reversal clears them; replaces pk_protect_columns)
        IF OLD.refund_cash_entry_id IS NOT NULL OR OLD.shortfall_transfer_id IS NOT NULL THEN
          RAISE EXCEPTION 'settlements %: settlement links are set once per settlement', OLD.id USING ERRCODE = '42501';
        END IF;
        IF NEW.settlement_type = 'none' THEN
          IF NEW.difference <> 0 OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL THEN
            RAISE EXCEPTION 'settlements %: nothing to settle expected', OLD.id USING ERRCODE = '23514';
          END IF;
        ELSIF NEW.settlement_type = 'refund' THEN
          SELECT direction::text AS direction, amount, source_type::text AS source_type, expense_request_id, status::text AS status
            INTO ce FROM cash_entries WHERE id = NEW.refund_cash_entry_id;
          IF NOT FOUND OR NEW.shortfall_transfer_id IS NOT NULL OR ce.direction <> 'in' OR ce.source_type <> 'settlement_refund'
             OR ce.status <> 'posted' OR ce.expense_request_id IS DISTINCT FROM NEW.request_id OR ce.amount <> NEW.difference THEN
            RAISE EXCEPTION 'settlements %: refund must be a posted KM of exactly the surplus', OLD.id USING ERRCODE = '23514';
          END IF;
        ELSE
          SELECT kind::text AS kind, amount, request_id, status::text AS status INTO tr FROM transfers WHERE id = NEW.shortfall_transfer_id;
          IF NOT FOUND OR NEW.refund_cash_entry_id IS NOT NULL OR tr.kind <> 'lpj_shortfall' OR tr.status <> 'posted'
             OR tr.request_id IS DISTINCT FROM NEW.request_id OR tr.amount <> -NEW.difference THEN
            RAISE EXCEPTION 'settlements %: shortfall must be a posted transfer of exactly the shortfall', OLD.id USING ERRCODE = '23514';
          END IF;
        END IF;
      END IF;

      IF reversing THEN
        -- E9: only a settlement that moved money; its KM / transfer must already be void; links and
        -- settle stamps cleared; reversal counter +1 with actor, time and reason.
        IF OLD.settlement_type NOT IN ('refund', 'shortfall') THEN
          RAISE EXCEPTION 'settlements %: nothing to reverse (settlement type %)', OLD.id, OLD.settlement_type USING ERRCODE = '42501';
        END IF;
        IF NEW.settled_at IS NOT NULL OR NEW.settled_by_id IS NOT NULL OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL
           OR NEW.reversal_count IS DISTINCT FROM coalesce(OLD.reversal_count, 0) + 1 OR NEW.last_reversed_at IS NULL
           OR NEW.last_reversed_by_id IS NULL OR length(coalesce(NEW.last_reversal_reason, '')) < 3 THEN
          RAISE EXCEPTION 'settlements %: reversal must clear the settlement and record count, actor and reason', OLD.id USING ERRCODE = '23514';
        END IF;
        IF OLD.settlement_type = 'refund' AND NOT EXISTS (SELECT 1 FROM cash_entries WHERE id = OLD.refund_cash_entry_id AND status = 'void') THEN
          RAISE EXCEPTION 'settlements %: reverse only after the refund KM is void', OLD.id USING ERRCODE = '23514';
        END IF;
        IF OLD.settlement_type = 'shortfall' AND NOT EXISTS (SELECT 1 FROM transfers WHERE id = OLD.shortfall_transfer_id AND status = 'void') THEN
          RAISE EXCEPTION 'settlements %: reverse only after the shortfall transfer is void', OLD.id USING ERRCODE = '23514';
        END IF;
      END IF;
      RETURN NEW;
    END
    $fn$;
  `)
}

/**
 * Rollback (pre-go-live of this release only). Refused while a shortfall re-approval exists (decision rows are
 * append-only, the LPJ state would be lost) or an audit row uses a new action — restore the pre-deploy dump
 * instead. Restores the E9 settlements guard, the MC1 G1 trigger, the approvals owner CHECK and company-refs
 * trigger, drops the tolerance trigger and the columns, and re-creates both enums without the new values.
 */
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
    DO $pk$
    BEGIN
      IF EXISTS (SELECT 1 FROM approvals WHERE doc_type::text = 'expense_shortfall') OR EXISTS (SELECT 1 FROM settlements WHERE shortfall_approval_status IS NOT NULL) THEN
        RAISE EXCEPTION 'qa_finance_integrity down: LPJ shortfall re-approvals exist; not rolling back (restore the dump)';
      END IF;
      IF EXISTS (SELECT 1 FROM audit_logs WHERE action::text IN ('overdraft_confirmed', 'bank_unverified_confirmed')) THEN
        RAISE EXCEPTION 'qa_finance_integrity down: audit rows overdraft_confirmed / bank_unverified_confirmed exist (append-only); not rolling back (restore the dump)';
      END IF;
    END
    $pk$;

    DROP TRIGGER IF EXISTS transfers_shortfall_tolerance ON transfers;
    DROP FUNCTION IF EXISTS pk_transfers_shortfall_tolerance();

    DROP TRIGGER IF EXISTS approvals_company_refs ON approvals;
    CREATE TRIGGER approvals_company_refs BEFORE INSERT OR UPDATE ON approvals FOR EACH ROW
      EXECUTE FUNCTION pk_same_company('request_id', 'expense_requests', 'addendum_id', 'budget_addenda', 'employee_id', 'employees');
    DROP INDEX IF EXISTS approvals_settlement_one_decision_per_level;
    DROP INDEX IF EXISTS approvals_settlement_one_position_per_person;

    CREATE OR REPLACE FUNCTION pk_approvals_before_insert() RETURNS trigger LANGUAGE plpgsql AS $fn$
    DECLARE
      creator integer;
    BEGIN
      NEW.decided_at := clock_timestamp();
      IF NEW.position IN ('diketahui', 'approval') THEN
        IF NEW.doc_type = 'budget_addendum' THEN
          SELECT created_by_id INTO creator FROM budget_addenda WHERE id = NEW.addendum_id;
          IF NEW.actor_id IS NULL OR creator IS NULL OR NEW.actor_id = creator THEN
            RAISE EXCEPTION 'approvals: the addendum creator cannot hold a decision position (G1)' USING ERRCODE = '42501';
          END IF;
          RETURN NEW;
        END IF;
        SELECT created_by_id INTO creator FROM expense_requests WHERE id = NEW.request_id;
        IF NEW.actor_id IS NULL OR NEW.actor_id = creator OR EXISTS (
             SELECT 1 FROM expense_requests_rels r JOIN company_memberships m ON m.employee_id = r.employees_id
             WHERE r.parent_id = NEW.request_id AND r.path = 'requesters' AND m.user_id = NEW.actor_id) THEN
          RAISE EXCEPTION 'approvals: requester/creator cannot hold a decision position (G1)' USING ERRCODE = '42501';
        END IF;
      END IF;
      RETURN NEW;
    END
    $fn$;
`)

  // E9 settlements guard, verbatim
  await db.execute(sql`
    CREATE OR REPLACE FUNCTION pk_settlements_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
    DECLARE
      r record;
      o jsonb;
      n jsonb;
      submit_cols text[] := ARRAY['usage_notes', 'transferred_total', 'receipts_total', 'difference', 'submit_count',
                                  'submitted_at', 'submitted_by_id', 'doc_no'];
      verify_cols text[] := ARRAY['transferred_total', 'verified_receipts_total', 'difference', 'settlement_type',
                                  'verified_at', 'verified_by_id'];
      settle_cols text[] := ARRAY['settled_at', 'settled_by_id', 'refund_cash_entry_id', 'shortfall_transfer_id'];
      reverse_cols text[] := ARRAY['reversal_count', 'last_reversed_at', 'last_reversed_by_id', 'last_reversal_reason'];
      always text[] := ARRAY['status', 'updated_at'];
      allowed text[];
      reversing boolean;
      ce record;
      tr record;
    BEGIN
      SELECT type::text AS type, status::text AS status INTO r FROM expense_requests WHERE id = NEW.request_id;
      IF TG_OP = 'INSERT' THEN
        IF r.type IS DISTINCT FROM 'advance' THEN
          RAISE EXCEPTION 'settlements: LPJ exists only for Uang Muka (request %)', NEW.request_id USING ERRCODE = '42501';
        END IF;
        IF NEW.status <> 'draft' OR NEW.doc_no IS NOT NULL OR NEW.settled_at IS NOT NULL OR NEW.verified_at IS NOT NULL
           OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL
           OR coalesce(NEW.reversal_count, 0) <> 0 OR NEW.last_reversed_at IS NOT NULL OR NEW.last_reversed_by_id IS NOT NULL
           OR NEW.last_reversal_reason IS NOT NULL THEN
          RAISE EXCEPTION 'settlements: new LPJ rows are drafts' USING ERRCODE = '42501';
        END IF;
        RETURN NEW;
      END IF;

      o := to_jsonb(OLD);
      n := to_jsonb(NEW);
      -- E9: the ONLY change of a settled row is the reversal settled → verified (Finance, reason).
      reversing := OLD.status = 'settled' AND NEW.status = 'verified';
      IF OLD.status = 'settled' AND NOT reversing AND (o - 'updated_at') IS DISTINCT FROM (n - 'updated_at') THEN
        RAISE EXCEPTION 'settlements %: settled LPJ is immutable', OLD.id USING ERRCODE = '42501';
      END IF;
      IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
           (OLD.status = 'draft' AND NEW.status = 'submitted') OR (OLD.status = 'submitted' AND NEW.status IN ('revision', 'verified'))
           OR (OLD.status = 'revision' AND NEW.status = 'submitted') OR (OLD.status = 'verified' AND NEW.status = 'settled')
           OR reversing) THEN
        RAISE EXCEPTION 'settlements %: status % → % not allowed', OLD.id, OLD.status, NEW.status USING ERRCODE = '42501';
      END IF;
      allowed := always;
      IF NEW.status = 'submitted' AND OLD.status IN ('draft', 'revision') THEN allowed := allowed || submit_cols; END IF;
      IF NEW.status = 'revision' AND OLD.status = 'submitted' THEN allowed := allowed || ARRAY['finance_notes']; END IF;
      IF NEW.status = 'verified' AND OLD.status = 'submitted' THEN allowed := allowed || verify_cols; END IF;
      IF NEW.status = 'settled' AND OLD.status = 'verified' THEN allowed := allowed || settle_cols; END IF;
      IF reversing THEN allowed := allowed || settle_cols || reverse_cols; END IF;
      IF (o - allowed) IS DISTINCT FROM (n - allowed) THEN
        RAISE EXCEPTION 'settlements %: columns outside the % transition cannot change', OLD.id, NEW.status USING ERRCODE = '42501';
      END IF;

      IF NEW.status = 'verified' AND OLD.status = 'submitted' THEN
        IF NEW.verified_receipts_total IS NULL OR NEW.transferred_total IS NULL
           OR NEW.difference IS DISTINCT FROM NEW.transferred_total - NEW.verified_receipts_total
           OR NEW.settlement_type IS DISTINCT FROM (CASE WHEN NEW.difference > 0 THEN 'refund' WHEN NEW.difference < 0 THEN 'shortfall' ELSE 'none' END)::enum_settlements_settlement_type THEN
          RAISE EXCEPTION 'settlements %: verified totals are inconsistent', OLD.id USING ERRCODE = '23514';
        END IF;
      END IF;

      IF NEW.status = 'settled' AND OLD.status = 'verified' THEN
        -- links are set once per settlement cycle (a reversal clears them; replaces pk_protect_columns)
        IF OLD.refund_cash_entry_id IS NOT NULL OR OLD.shortfall_transfer_id IS NOT NULL THEN
          RAISE EXCEPTION 'settlements %: settlement links are set once per settlement', OLD.id USING ERRCODE = '42501';
        END IF;
        IF NEW.settlement_type = 'none' THEN
          IF NEW.difference <> 0 OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL THEN
            RAISE EXCEPTION 'settlements %: nothing to settle expected', OLD.id USING ERRCODE = '23514';
          END IF;
        ELSIF NEW.settlement_type = 'refund' THEN
          SELECT direction::text AS direction, amount, source_type::text AS source_type, expense_request_id, status::text AS status
            INTO ce FROM cash_entries WHERE id = NEW.refund_cash_entry_id;
          IF NOT FOUND OR NEW.shortfall_transfer_id IS NOT NULL OR ce.direction <> 'in' OR ce.source_type <> 'settlement_refund'
             OR ce.status <> 'posted' OR ce.expense_request_id IS DISTINCT FROM NEW.request_id OR ce.amount <> NEW.difference THEN
            RAISE EXCEPTION 'settlements %: refund must be a posted KM of exactly the surplus', OLD.id USING ERRCODE = '23514';
          END IF;
        ELSE
          SELECT kind::text AS kind, amount, request_id, status::text AS status INTO tr FROM transfers WHERE id = NEW.shortfall_transfer_id;
          IF NOT FOUND OR NEW.refund_cash_entry_id IS NOT NULL OR tr.kind <> 'lpj_shortfall' OR tr.status <> 'posted'
             OR tr.request_id IS DISTINCT FROM NEW.request_id OR tr.amount <> -NEW.difference THEN
            RAISE EXCEPTION 'settlements %: shortfall must be a posted transfer of exactly the shortfall', OLD.id USING ERRCODE = '23514';
          END IF;
        END IF;
      END IF;

      IF reversing THEN
        -- E9: only a settlement that moved money; its KM / transfer must already be void; links and
        -- settle stamps cleared; reversal counter +1 with actor, time and reason.
        IF OLD.settlement_type NOT IN ('refund', 'shortfall') THEN
          RAISE EXCEPTION 'settlements %: nothing to reverse (settlement type %)', OLD.id, OLD.settlement_type USING ERRCODE = '42501';
        END IF;
        IF NEW.settled_at IS NOT NULL OR NEW.settled_by_id IS NOT NULL OR NEW.refund_cash_entry_id IS NOT NULL OR NEW.shortfall_transfer_id IS NOT NULL
           OR NEW.reversal_count IS DISTINCT FROM coalesce(OLD.reversal_count, 0) + 1 OR NEW.last_reversed_at IS NULL
           OR NEW.last_reversed_by_id IS NULL OR length(coalesce(NEW.last_reversal_reason, '')) < 3 THEN
          RAISE EXCEPTION 'settlements %: reversal must clear the settlement and record count, actor and reason', OLD.id USING ERRCODE = '23514';
        END IF;
        IF OLD.settlement_type = 'refund' AND NOT EXISTS (SELECT 1 FROM cash_entries WHERE id = OLD.refund_cash_entry_id AND status = 'void') THEN
          RAISE EXCEPTION 'settlements %: reverse only after the refund KM is void', OLD.id USING ERRCODE = '23514';
        END IF;
        IF OLD.settlement_type = 'shortfall' AND NOT EXISTS (SELECT 1 FROM transfers WHERE id = OLD.shortfall_transfer_id AND status = 'void') THEN
          RAISE EXCEPTION 'settlements %: reverse only after the shortfall transfer is void', OLD.id USING ERRCODE = '23514';
        END IF;
      END IF;
      RETURN NEW;
    END
    $fn$;
  `)

  await db.execute(sql`
  ALTER TABLE "approvals" DROP CONSTRAINT IF EXISTS "approvals_settlement_id_settlements_id_fk";
  DROP INDEX IF EXISTS "approvals_settlement_idx";
  ALTER TABLE "approvals" DROP COLUMN IF EXISTS "settlement_id";
  ALTER TABLE settlements DROP CONSTRAINT IF EXISTS settlements_shortfall_approval;
  ALTER TABLE companies DROP CONSTRAINT IF EXISTS companies_shortfall_tolerance_pct;
  ALTER TABLE "companies" DROP COLUMN IF EXISTS "shortfall_tolerance_pct";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_status";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_cycle";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_level";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_amount";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_snapshot";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_approval_note";
  ALTER TABLE "settlements" DROP COLUMN IF EXISTS "shortfall_reject_reason";
  DROP TYPE IF EXISTS "public"."enum_settlements_shortfall_approval_status";
  ALTER TABLE "approvals" DROP CONSTRAINT IF EXISTS approvals_owner_doc;
  ALTER TABLE "approvals" ALTER COLUMN "doc_type" DROP DEFAULT;
  ALTER TABLE "approvals" ALTER COLUMN "doc_type" SET DATA TYPE text;
  DROP TYPE "public"."enum_approvals_doc_type";
  CREATE TYPE "public"."enum_approvals_doc_type" AS ENUM('expense_request', 'budget_addendum');
  ALTER TABLE "approvals" ALTER COLUMN "doc_type" SET DATA TYPE "public"."enum_approvals_doc_type" USING "doc_type"::"public"."enum_approvals_doc_type";
  ALTER TABLE "approvals" ALTER COLUMN "doc_type" SET DEFAULT 'expense_request'::"public"."enum_approvals_doc_type";
  ALTER TABLE approvals ADD CONSTRAINT approvals_owner_doc CHECK (
    (doc_type = 'expense_request' AND request_id IS NOT NULL AND addendum_id IS NULL)
    OR (doc_type = 'budget_addendum' AND addendum_id IS NOT NULL AND request_id IS NULL));
  ALTER TABLE "audit_logs" ALTER COLUMN "action" SET DATA TYPE text;
  DROP TYPE "public"."enum_audit_logs_action";
  CREATE TYPE "public"."enum_audit_logs_action" AS ENUM('create', 'update', 'status_change', 'deactivate', 'reactivate', 'delete_attempt', 'void', 'view_sensitive', 'login', 'logout', 'login_failed', 'session_revoked', 'role_change', 'role_sync', 'device_register', 'device_revoke', 'number_issued', 'export', 'print', 'sign', 'acknowledge', 'flag_raised', 'flag_reviewed', 'sync_odoo', 'sync_offline', 'period_close', 'period_reopen', 'schema_maintenance', 'email_test', 'approve', 'reject', 'verify', 'acknowledge_delegated', 'access_denied', 'approval_skipped', 'retention_purge', 'import', '2fa_enabled', '2fa_disabled', 'privacy_ack');
  ALTER TABLE "audit_logs" ALTER COLUMN "action" SET DATA TYPE "public"."enum_audit_logs_action" USING "action"::"public"."enum_audit_logs_action";`)
}
